/**
 * heartbeat-context — JS cron handler (pre-compute agent context).
 *
 * Runs before each heartbeat, gathers common situational data that agents
 * currently waste 10-40 bash calls discovering:
 *   - Recent session counts by agent
 *   - Session sizes (cost proxy)
 *   - Error counts from ERROR_LOGs
 *
 * Writes a compact summary to agents/<agent>/workspace/heartbeat-context.md
 * that gets injected into the cron message. Agents skip the "situational
 * awareness" bash calls and start working immediately.
 *
 * Estimated savings: 10-20 bash calls per heartbeat × 4-6 agents × 2/hour
 *   = 80-240 fewer tool calls/hour ≈ 15-30% token reduction per heartbeat.
 *
 * Original: agents/optimizer/workspace/patches/heartbeat-context-handler.ts
 * Adapted to HandlerModule["create"] signature by tech-lead (2026-03-21).
 *
 * Exports create() conforming to HandlerModule.
 */

import {
  readdirSync,
  readFileSync,
  existsSync,
  statSync,
  writeFileSync,
  mkdirSync,
} from "node:fs";
import { join } from "node:path";
import type { HandlerContext, HandlerModule } from "../../../src/lib/handler-context.js";
import type { CronEntry } from "../../../src/lib/cron-tool.js";

// ── Configuration ─────────────────────────────────────────────────────

/** How far back to look for recent sessions (6 hours). */
const SESSION_WINDOW_MS = 6 * 60 * 60 * 1000;

/** Maximum recent sessions to analyze per run. */
const MAX_SESSIONS_TO_SCAN = 100;

/** Agents to generate context for. */
const CONTEXT_AGENTS = [
  "optimizer",
  "coach",
  "tech-lead",
  "bob",
  "scout",
  "amy-kimi",
  "qa",
  "evaluator",
];

// ── Types ─────────────────────────────────────────────────────────────

interface SessionInfo {
  id: string;
  agent: string;
  status: string;
  sizeKB: number;
  startedAt: number;
  task: string;
}

interface AgentSummary {
  sessions: number;
  totalKB: number;
  avgKB: number;
  errors: number;
  largestSession: { id: string; sizeKB: number; task: string } | null;
}

interface SystemSnapshot {
  windowHours: number;
  totalSessions: number;
  totalKB: number;
  errorRate: number;
  byAgent: Record<string, AgentSummary>;
  recentErrors: { agent: string; code: string; count: number }[];
  generatedAt: string;
}

// ── Core Logic ────────────────────────────────────────────────────────

function scanRecentSessions(baseDir: string, windowMs: number): SessionInfo[] {
  const historyDir = join(baseDir, ".state", "sessions", "history");
  if (!existsSync(historyDir)) return [];

  const cutoff = Date.now() - windowMs;
  const entries = readdirSync(historyDir).filter((d) => d.startsWith("s_"));

  // Sort by timestamp descending, take only MAX_SESSIONS_TO_SCAN
  const sorted = entries
    .map((d) => {
      const match = d.match(/^s_(\d+)_/);
      return { dir: d, ts: match ? parseInt(match[1]) : 0 };
    })
    .filter((e) => e.ts >= cutoff)
    .sort((a, b) => b.ts - a.ts)
    .slice(0, MAX_SESSIONS_TO_SCAN);

  const sessions: SessionInfo[] = [];

  for (const entry of sorted) {
    const metaPath = join(historyDir, entry.dir, "meta.json");
    if (!existsSync(metaPath)) continue;

    try {
      const meta = JSON.parse(readFileSync(metaPath, "utf-8"));
      const sessionDir = join(historyDir, entry.dir);

      // Get total directory size
      let sizeKB = 0;
      try {
        const files = readdirSync(sessionDir);
        for (const f of files) {
          const fPath = join(sessionDir, f);
          try {
            const st = statSync(fPath);
            if (st.isFile()) sizeKB += Math.ceil(st.size / 1024);
          } catch {
            /* skip */
          }
        }
      } catch {
        /* skip */
      }

      sessions.push({
        id: entry.dir,
        agent: meta.agent || "unknown",
        status: meta.status || "unknown",
        sizeKB,
        startedAt: meta.startedAt || entry.ts,
        task: (meta.task || "").slice(0, 100),
      });
    } catch {
      /* skip malformed meta */
    }
  }

  return sessions;
}

function scanErrorLogs(
  baseDir: string,
  windowMs: number,
): { agent: string; code: string; count: number }[] {
  const agentsDir = join(baseDir, "agents");
  if (!existsSync(agentsDir)) return [];

  const cutoff = Date.now() - windowMs;
  const errorCounts: Record<string, number> = {};

  let agentDirs: string[];
  try {
    agentDirs = readdirSync(agentsDir).filter((d) => {
      const p = join(agentsDir, d);
      return existsSync(join(p, "ERROR_LOG.jsonl"));
    });
  } catch {
    return [];
  }

  for (const agentName of agentDirs) {
    const logPath = join(agentsDir, agentName, "ERROR_LOG.jsonl");
    try {
      const lines = readFileSync(logPath, "utf-8").split("\n").filter(Boolean);
      for (const line of lines) {
        try {
          const entry = JSON.parse(line);
          const ts = entry.timestamp ? new Date(entry.timestamp).getTime() : 0;
          if (ts < cutoff) continue;

          const code = (entry.error || "").split(":")[0].trim();
          if (code) {
            const key = `${agentName}:${code}`;
            errorCounts[key] = (errorCounts[key] || 0) + 1;
          }
        } catch {
          /* skip */
        }
      }
    } catch {
      /* skip */
    }
  }

  return Object.entries(errorCounts)
    .map(([key, count]) => {
      const [agent, code] = key.split(":");
      return { agent, code, count };
    })
    .sort((a, b) => b.count - a.count)
    .slice(0, 15); // Top 15 errors
}

function buildSnapshot(baseDir: string): SystemSnapshot {
  const sessions = scanRecentSessions(baseDir, SESSION_WINDOW_MS);
  const errors = scanErrorLogs(baseDir, SESSION_WINDOW_MS);

  const windowHours = SESSION_WINDOW_MS / (60 * 60 * 1000);
  const byAgent: Record<string, AgentSummary> = {};
  let totalErrors = 0;

  for (const s of sessions) {
    if (!byAgent[s.agent]) {
      byAgent[s.agent] = {
        sessions: 0,
        totalKB: 0,
        avgKB: 0,
        errors: 0,
        largestSession: null,
      };
    }
    const a = byAgent[s.agent];
    a.sessions++;
    a.totalKB += s.sizeKB;
    if (s.status === "error") {
      a.errors++;
      totalErrors++;
    }
    if (!a.largestSession || s.sizeKB > a.largestSession.sizeKB) {
      a.largestSession = { id: s.id, sizeKB: s.sizeKB, task: s.task };
    }
  }

  for (const a of Object.values(byAgent)) {
    a.avgKB = a.sessions > 0 ? Math.round(a.totalKB / a.sessions) : 0;
  }

  return {
    windowHours,
    totalSessions: sessions.length,
    totalKB: sessions.reduce((sum, s) => sum + s.sizeKB, 0),
    errorRate:
      sessions.length > 0
        ? Math.round((totalErrors / sessions.length) * 1000) / 10
        : 0,
    byAgent,
    recentErrors: errors,
    generatedAt: new Date().toISOString(),
  };
}

// ── Formatters ────────────────────────────────────────────────────────

function formatSnapshot(snap: SystemSnapshot): string {
  const lines: string[] = [];
  lines.push(
    `# System Context (auto-generated ${snap.generatedAt.slice(0, 16)})`,
  );
  lines.push("");
  lines.push(
    `**${snap.windowHours}h window:** ${snap.totalSessions} sessions, ${snap.totalKB}KB total, ${snap.errorRate}% error rate`,
  );
  lines.push("");

  // Agent table
  lines.push("| Agent | Sessions | Total KB | Avg KB | Errors |");
  lines.push("|-------|----------|----------|--------|--------|");

  const sorted = Object.entries(snap.byAgent).sort(
    ([, a], [, b]) => b.totalKB - a.totalKB,
  );
  for (const [name, data] of sorted) {
    lines.push(
      `| ${name} | ${data.sessions} | ${data.totalKB} | ${data.avgKB} | ${data.errors} |`,
    );
  }

  // Top cost sessions
  lines.push("");
  lines.push("**Largest sessions:**");
  const largestSessions = sorted
    .filter(([, d]) => d.largestSession)
    .map(([name, d]) => ({ name, ...d.largestSession! }))
    .sort((a, b) => b.sizeKB - a.sizeKB)
    .slice(0, 5);

  for (const s of largestSessions) {
    lines.push(`- ${s.sizeKB}KB ${s.name}: ${s.task.slice(0, 80)}`);
  }

  // Error patterns
  if (snap.recentErrors.length > 0) {
    lines.push("");
    lines.push("**Active error patterns (6h):**");
    for (const e of snap.recentErrors.slice(0, 8)) {
      lines.push(`- ${e.agent} ${e.code}: ${e.count}x`);
    }
  }

  lines.push("");
  return lines.join("\n");
}

function formatAgentContext(snap: SystemSnapshot, agentName: string): string {
  const lines: string[] = [];
  const myData = snap.byAgent[agentName];

  lines.push(
    `# Your Context (auto-generated ${snap.generatedAt.slice(0, 16)})`,
  );
  lines.push("");
  lines.push(
    `**System:** ${snap.totalSessions} sessions/${snap.windowHours}h, ${snap.errorRate}% error rate`,
  );

  if (myData) {
    lines.push(
      `**You:** ${myData.sessions} sessions, ${myData.totalKB}KB total (${myData.avgKB}KB avg)`,
    );
    if (myData.errors > 0) {
      lines.push(`**⚠️ Your errors:** ${myData.errors} error sessions`);
    }
  }

  lines.push("");
  lines.push("**Top spenders:**");
  const sorted = Object.entries(snap.byAgent)
    .sort(([, a], [, b]) => b.totalKB - a.totalKB)
    .slice(0, 5);
  for (const [name, data] of sorted) {
    const marker = name === agentName ? " ← you" : "";
    lines.push(`- ${name}: ${data.sessions}s, ${data.totalKB}KB${marker}`);
  }

  // Show this agent's errors
  const myErrors = snap.recentErrors.filter((e) => e.agent === agentName);
  if (myErrors.length > 0) {
    lines.push("");
    lines.push("**Your active error patterns:**");
    for (const e of myErrors) {
      lines.push(`- ${e.code}: ${e.count}x`);
    }
  }

  lines.push("");
  return lines.join("\n");
}

// ── Handler Module (correct HandlerModule["create"] signature) ────────

export const create: HandlerModule["create"] = (
  ctx: HandlerContext,
  _entry: CronEntry,
) => {
  return async () => {
    const baseDir = process.cwd();
    const snap = buildSnapshot(baseDir);
    const formatted = formatSnapshot(snap);

    // Ensure shared workspace exists
    const sharedWorkspace = join(baseDir, "agents", "shared", "workspace");
    if (!existsSync(sharedWorkspace)) {
      mkdirSync(sharedWorkspace, { recursive: true });
    }

    // Write system-wide context
    const outPath = join(sharedWorkspace, "system-context.md");
    writeFileSync(outPath, formatted, "utf-8");

    // Write per-agent context files (with nudge injection per brief-active-nudging.md §3)
    let written = 0;
    let nudgesInjected = 0;
    for (const agentName of CONTEXT_AGENTS) {
      const agentWorkspace = join(baseDir, "agents", agentName, "workspace");
      if (existsSync(agentWorkspace)) {
        let agentContext = "";

        // Check for active nudge file — prepend with URGENT priority
        const nudgePath = join(agentWorkspace, "nudge-active.md");
        if (existsSync(nudgePath)) {
          try {
            const nudgeContent = readFileSync(nudgePath, "utf-8").trim();
            if (nudgeContent) {
              agentContext += `# ⚠️ URGENT — Active Nudge\n\n`;
              agentContext += nudgeContent;
              agentContext += `\n\n---\n\n`;
              nudgesInjected++;
            }
          } catch {
            /* skip unreadable nudge file */
          }
        }

        agentContext += formatAgentContext(snap, agentName);
        writeFileSync(
          join(agentWorkspace, "heartbeat-context.md"),
          agentContext,
          "utf-8",
        );
        written++;
      }
    }

    // Log result via notify (shows in cron output)
    const nudgeNote = nudgesInjected > 0 ? ` ${nudgesInjected} active nudge(s) injected.` : "";
    const summary = `Generated system context: ${snap.totalSessions} sessions, ${snap.totalKB}KB in ${snap.windowHours}h window. Context files written for ${written} agents.${nudgeNote}`;
    ctx.notify(summary);
  };
};

/**
 * audit-requests — JS cron handler (Phase 4 of request-tracking).
 *
 * Runs every 2h to reconcile request lifecycle:
 * 1. Auto-expires stale CREATED `send` requests older than 4h
 *    (they've been injected into multiple heartbeats by then — continuing
 *    to inject them wastes ~$58/day in tokens at 31 stuck requests)
 * 2. Auto-expires stale CREATED `call` requests to non-agent targets (e.g. "finish")
 *    older than 1h (these are tracking artifacts, not real requests)
 * 3. Resets IN_PROGRESS requests older than 4h with no active session → CREATED
 * 4. Archives COMPLETED/FAILED requests older than 7 days
 *
 * Exports create() conforming to HandlerModule.
 */

import { readdirSync, existsSync } from "node:fs";
import { join } from "node:path";
import type { HandlerContext, HandlerModule } from "../../../src/lib/handler-context.js";
import type { CronEntry } from "../../../src/lib/cron-tool.js";
import { getDb } from "../../../src/lib/requests.js";

// ── Configuration ─────────────────────────────────────────────────────

/** Send requests older than this in CREATED status get auto-expired. */
const STALE_SEND_MS = 4 * 60 * 60 * 1000; // 4 hours

/** Non-agent call requests (e.g. "finish") older than this get auto-expired. */
const STALE_NONAGENT_CALL_MS = 1 * 60 * 60 * 1000; // 1 hour

/** Requests older than this in IN_PROGRESS with no active session get reset. */
const STALE_IN_PROGRESS_MS = 4 * 60 * 60 * 1000; // 4 hours

/** Completed/failed requests older than this get archived (deleted). */
const ARCHIVE_DAYS = 7;

/** Known agent names — requests to anything else are tracking artifacts. */
const KNOWN_AGENTS = new Set([
  "may", "bob", "optimizer", "coach", "tech-lead", "evaluator",
  "scout", "qa", "coder", "amy", "amy-kimi",
]);

// ── Types ─────────────────────────────────────────────────────────────

interface RequestRow {
  requestId: string;
  status: string;
  method: string;
  toAgent: string;
  sessionId: string | null;
  createdAt: number;
  completedAt: number | null;
  summary: string | null;
}

// ── Factory ───────────────────────────────────────────────────────────

export const create: HandlerModule["create"] = (ctx: HandlerContext, _entry: CronEntry) => {
  return async () => {
    let db: ReturnType<typeof getDb>;
    try {
      db = getDb(ctx.persistDir);
    } catch {
      ctx.log("[audit-requests] DB not available, skipping audit.");
      return;
    }

    const now = Date.now();
    let expiredSends = 0;
    let expiredNonAgent = 0;

    // 1. Auto-expire stale CREATED `send` requests (> 4h)
    //    These have been injected into enough heartbeats. Keeping them
    //    just bloats context and wastes tokens.
    try {
      const staleSends = db.query(
        `SELECT * FROM requests WHERE status = 'CREATED' AND method = 'send' AND createdAt < ?`
      ).all(now - STALE_SEND_MS) as RequestRow[];

      for (const req of staleSends) {
        try {
          db.query(
            `UPDATE requests SET status = ?, summary = ?, completedAt = ?, updatedAt = ? WHERE requestId = ?`
          ).run(
            "COMPLETED",
            `Auto-expired after ${Math.round((now - req.createdAt) / 3600000)}h (injected into heartbeats, presumed processed)`,
            now,
            now,
            req.requestId,
          );
          expiredSends++;
        } catch {
          ctx.log(`[audit-requests] Failed to expire send request ${req.requestId}`);
        }
      }
    } catch {
      ctx.log("[audit-requests] Failed to query stale send requests.");
    }

    if (expiredSends > 0) {
      ctx.log(
        `[audit-requests] Auto-expired ${expiredSends} stale CREATED send request(s) older than ${STALE_SEND_MS / 3600000}h.`
      );
    }

    // 2. Auto-expire stale CREATED `call` requests to non-agent targets
    //    e.g. "bob -> finish" — these are tracking artifacts from the finish() tool
    try {
      const staleCallRows = db.query(
        `SELECT * FROM requests WHERE status = 'CREATED' AND method = 'call' AND createdAt < ?`
      ).all(now - STALE_NONAGENT_CALL_MS) as RequestRow[];

      const staleNonAgent = staleCallRows.filter(r => !KNOWN_AGENTS.has(r.toAgent));

      for (const req of staleNonAgent) {
        try {
          db.query(
            `UPDATE requests SET status = ?, summary = ?, completedAt = ?, updatedAt = ? WHERE requestId = ?`
          ).run(
            "COMPLETED",
            `Auto-expired: non-agent call target "${req.toAgent}" (tracking artifact)`,
            now,
            now,
            req.requestId,
          );
          expiredNonAgent++;
        } catch {
          ctx.log(`[audit-requests] Failed to expire non-agent request ${req.requestId}`);
        }
      }
    } catch {
      ctx.log("[audit-requests] Failed to query stale non-agent call requests.");
    }

    if (expiredNonAgent > 0) {
      ctx.log(
        `[audit-requests] Auto-expired ${expiredNonAgent} non-agent call request(s).`
      );
    }

    // 3. Reset orphaned IN_PROGRESS requests (> 4h, no active session)
    let resetCount = 0;
    try {
      const activeSessions = getActiveSessionIds(ctx.persistDir);
      const staleInProgress = db.query(
        `SELECT * FROM requests WHERE status = 'IN_PROGRESS' AND createdAt < ?`
      ).all(now - STALE_IN_PROGRESS_MS) as RequestRow[];

      const orphaned = staleInProgress.filter(
        r => !r.sessionId || !activeSessions.has(r.sessionId)
      );

      for (const req of orphaned) {
        try {
          db.query(
            `UPDATE requests SET status = 'CREATED', sessionId = NULL, updatedAt = ? WHERE requestId = ?`
          ).run(now, req.requestId);
          resetCount++;
        } catch {
          ctx.log(`[audit-requests] Failed to reset request ${req.requestId}`);
        }
      }
    } catch {
      ctx.log("[audit-requests] Failed to query stale in-progress requests.");
    }

    if (resetCount > 0) {
      ctx.log(`[audit-requests] Reset ${resetCount} orphaned IN_PROGRESS request(s) to CREATED.`);
    }

    // 4. Archive old completed/failed requests (> 7 days)
    let archived = 0;
    try {
      const archiveCutoff = now - ARCHIVE_DAYS * 86400000;
      const result = db.query(
        `DELETE FROM requests WHERE status IN ('COMPLETED', 'FAILED') AND completedAt < ?`
      ).run(archiveCutoff);
      archived = (result as { changes: number }).changes;
    } catch {
      ctx.log("[audit-requests] Failed to archive old requests.");
    }
    if (archived > 0) {
      ctx.log(`[audit-requests] Archived ${archived} completed/failed request(s) older than ${ARCHIVE_DAYS} days.`);
    }

    // Summary
    let activeCount = 0;
    try {
      const row = db.query(
        `SELECT COUNT(*) as count FROM requests WHERE status IN ('CREATED', 'IN_PROGRESS')`
      ).get() as { count: number } | null;
      activeCount = row?.count ?? 0;
    } catch {
      // DB query failed; leave at 0
    }
    ctx.log(
      `[audit-requests] Audit complete. Active: ${activeCount}, ` +
      `Expired sends: ${expiredSends}, Expired non-agent: ${expiredNonAgent}, ` +
      `Reset: ${resetCount}, Archived: ${archived}.`
    );
  };
};

// ── Helpers ───────────────────────────────────────────────────────────

/**
 * Get set of currently active session IDs by scanning .state/sessions/active/.
 */
function getActiveSessionIds(persistDir: string): Set<string> {
  const activeDir = join(persistDir, "sessions", "active");
  if (!existsSync(activeDir)) return new Set();
  try {
    return new Set(
      readdirSync(activeDir).filter(n => n.startsWith("s_"))
    );
  } catch {
    return new Set();
  }
}
